#pragma once
#include "../src/earth/VoxelTerrain.h"
#include <functional>
#include <numeric>
// The full-size cruiser is a separate workload. Never compare its timings
// against the old 12m test boat as if model complexity were unchanged.
inline void runNavalOceanPass(vsgraysim::earth::VoxelScene& scene,
 vsgraysim::viewport3d::VoxelSceneFeature& feature,
 vsgraysim::viewport3d::Viewport3DView& view,const std::filesystem::path& directory,
 const std::string& scenePath,
 const std::function<void(vsg::dvec3,vsg::dvec3)>& camera,
 const std::function<double()>& render,const std::function<double()>& nativeTime,
 const std::function<void(const std::string&)>& capture){
 using namespace vsgraysim;using namespace vsgraysim::earth;using namespace vsgraysim::viewport3d;using json=nlohmann::json;
 auto require=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};
 const auto initial=scene.snapshot();const auto& ship=initial->objects.at("vessel");const double mass=ship.massKg();const auto bounds=ship.localBounds();
 json r={{"scene",scenePath},{"model","FlightGear CG-57 high-detail, metre scale 1:1"},{"voxel_size_m",ship.volume->resolution_m},{"grid_dimensions",ship.volume->dimensions()},{"occupied_voxels",ship.volume->occupiedCount()},{"display_triangles",ship.surface().indices().size()/3},{"bounds_m",{{bounds.min.x,bounds.min.y,bounds.min.z},{bounds.max.x,bounds.max.y,bounds.max.z}}},{"mass_kg_assumed_bulk",mass},{"bulk_density_kg_m3",ship.material.at("density_kg_m3")},{"physical_scope","nominal source waterline and assumed homogeneous bulk density; no certified displacement, GM, flooding or propulsion"},{"effects_legacy",bool(std::getenv("VSGRAYSIM_OCEAN_LEGACY_EFFECTS"))},{"frames",json::array()}};
 auto overview=[&]{camera({160,58,200},{0,10,0});};overview();capture("cruiser-initial");
 // High-resolution detail evidence is separate from the 960x540 timing pass.
 // Resize the real Vulkan framebuffer, keeping physical state and UTC frozen.
 auto* top=view.window();top->setFixedSize(1920,1080);QApplication::processEvents(QEventLoop::AllEvents,50);for(int i=0;i<3;++i)render();r["detail_framebuffer_px"]={1920,1080};r["detail_views"]=json::array();
 auto detail=[&](const char* name,vsg::dvec3 eye,vsg::dvec3 target){const auto s=scene.snapshot();const auto pose=s->objects.at("vessel").pose(s->tick,s->fixedStep);camera(pose*eye,pose*target);render();capture(name);r["detail_views"].push_back({{"name",name},{"eye_object_m",{eye.x,eye.y,eye.z}},{"target_object_m",{target.x,target.y,target.z}}});};
 detail("cruiser-detail-stern-flight-deck",{32,17,-87},{0,7,-60});detail("cruiser-detail-bridge",{27,25,-12},{0,20,-12});detail("cruiser-detail-radar",{24,41,-12},{0,34,-12});detail("cruiser-detail-bow",{28,23,75},{0,10,52});detail("cruiser-detail-hull-number",{27,7,-66},{7,3,-62});
 top->setFixedSize(960,540);QApplication::processEvents(QEventLoop::AllEvents,50);for(int i=0;i<3;++i)render();
 r["detail_tick"]=scene.snapshot()->tick;r["detail_scope"]="frozen initial source-waterline pose; dynamic stability measured separately";
 if(std::getenv("VSGRAYSIM_NAVAL_DETAIL_ONLY")){std::ofstream(directory/"naval-detail-acceptance.json")<<r.dump(2)<<'\n';return;}
 overview();scene.saveCheckpoint((directory/"naval-initial-checkpoint.json").string());
 scene.setPaused(false);auto warm=scene.advanceTo(3.,256);scene.setPaused(true);require(!warm.pendingSteps,"naval warmup lost physics time");
 const auto c=ship.localCentreOfMass();scene.schedule({{"kind","impulse"},{"object","vessel"},{"tick",200},{"space","object"},{"point_m",{c.x,c.y,c.z}},{"impulse_ns",{0,0,-mass*1.2}}});
 size_t rangeChecks=0;double rangeError=0,minimum=1e30,maximum=-1e30;
 for(int i=0;i<60;++i){QElapsedTimer elapsed;elapsed.start();scene.setPaused(false);auto step=scene.advanceTo(3.04+i*.04,8);scene.setPaused(true);require(!step.pendingSteps,"naval pass lost physics time");const double update=elapsed.nsecsElapsed()/1e6,draw=render(),native=nativeTime();const auto s=scene.snapshot();const auto& body=s->objects.at("vessel");const auto centre=body.pose(s->tick,s->fixedStep)*body.localCentreOfMass();minimum=std::min(minimum,centre.y);maximum=std::max(maximum,centre.y);require(std::abs(body.massKg()-mass)<1e-4,"water changed cruiser voxel mass");
  for(const auto& [id,o]:s->objects)require(feature.display().placements.at(id)->matrix==o.pose(s->tick,s->fixedStep),"cruiser display differs from published rigid pose");
  for(double z:{-40.,0.,40.}){auto a=raycastVoxelScene(*s,{0,100,z},{0,-1,0},130);auto b=scene.rigidRaycast({0,100,z},{0,-1,0},130);if(a&&a->object=="vessel"){require(b&&b->object==a->object,"Bullet missed a visible cruiser surface");++rangeChecks;rangeError=std::max(rangeError,std::abs(a->distance-b->distance));}else if(b&&b->object=="vessel")require(a&&a->object=="vessel","Bullet produced a hidden cruiser surface");}
  r["frames"].push_back({{"seconds",s->timeSeconds()},{"advance_simulation_ms",40},{"advance_wall_ms",update},{"render_submit_wait_ms",native},{"render_wall_ms",draw},{"buoyancy_wall_ms",step.buoyancyMs},{"water_drag_wall_ms",step.waterDragMs},{"water_total_wall_ms",step.waterMs},{"complete_wall_ms",update+draw},{"speed_mps",vsg::length(body.velocity)},{"centre_y_m",centre.y}});if(i%2==0)capture(QString("cruiser-route-%1").arg(i,3,10,QChar('0')).toStdString());
 }
 require(rangeChecks>=20,"naval pass did not compare enough physical cruiser rays");r["cpu_bullet_range_checks"]=rangeChecks;require(rangeError<.001,"cruiser Bullet/CPU surface range discrepancy exceeds 1mm");r["maximum_cpu_bullet_range_error_m"]=rangeError;r["heave_range_m"]={minimum,maximum};
 r["live_frames"]=json::array();const double liveBase=scene.snapshot()->timeSeconds();QElapsedTimer clock;clock.start();
 for(int i=1;i<=60;++i){while(clock.nsecsElapsed()/1e6<i*1000./30.)QThread::msleep(1);QElapsedTimer t;t.start();scene.setPaused(false);auto step=scene.advanceTo(liveBase+i/30.,8);scene.setPaused(true);require(!step.pendingSteps,"naval pacing dropped simulation ticks");const double update=t.nsecsElapsed()/1e6,draw=render();r["live_frames"].push_back({{"advance_wall_ms",update},{"render_submit_wait_ms",nativeTime()},{"render_wall_ms",draw},{"buoyancy_wall_ms",step.buoyancyMs},{"water_total_wall_ms",step.waterMs},{"complete_wall_ms",update+draw}});}
 r["live_simulation_seconds"]=2.;r["live_wall_seconds"]=clock.nsecsElapsed()/1e9;r["live_realtime_ratio"]=2./r["live_wall_seconds"].get<double>();
 overview();capture("cruiser-overview");camera({70,18,-90},{0,8,-25});capture("cruiser-stern-quarter");camera({-50,22,105},{0,8,42});capture("cruiser-bow-quarter");camera({20,8,-5},{0,8,-10});capture("cruiser-bridge-close");camera({40,.3,70},{0,2,20});capture("cruiser-waterline");camera({35,-4,35},{0,-4,0});capture("cruiser-underwater");
 scene.saveCheckpoint((directory/"naval-final-checkpoint.json").string());const auto original=scene.snapshot()->ocean->encode();r["weather_cases"]=json::array();
 auto weather=[&](const char* name,int day,double hour,double hs,double wind,double fog){auto o=original;o["wave_height_m"]=hs;o["wave_length_m"]=hs>1?42:24;o["wind_speed_mps"]=wind;o["sea_fog"]={{"visibility_m",fog},{"height_m",45}};o.erase("harmonics");scene.edit(json::array({{{"kind","ocean"},{"ocean",o}}}),scene.snapshot()->revision);if(auto* sky=view.featureAs<SkyFeature>(SkyFeature::kId))sky->configure({{"year",2026},{"month",9},{"day",day},{"hours_utc",hour}});overview();for(int i=0;i<3;++i)render();capture(name);std::vector<double> times;for(int i=0;i<15;++i){render();times.push_back(nativeTime());}std::sort(times.begin(),times.end());r["weather_cases"].push_back({{"name",name},{"utc",{{"year",2026},{"month",9},{"day",day},{"hours",hour}}},{"wind_wave_hs_m",hs},{"wind_mps",wind},{"fog_visibility_m",fog},{"render_submit_wait_median_ms",times[times.size()/2]}});};
 weather("cruiser-sunset",10,9.5,.65,6,0);weather("cruiser-night",26,12,.65,6,0);weather("cruiser-marine-fog",10,4,.65,6,2000);weather("cruiser-rough-sea",10,4,2.1,14,0);
 // Keep the naval ship in the background while its small fractured test
 // companion enters the water. These visual droplets add no collision bodies.
 scene.edit(json::array({{{"kind","ocean"},{"ocean",original}}}),scene.snapshot()->revision);if(auto* sky=view.featureAs<SkyFeature>(SkyFeature::kId))sky->configure({{"year",2026},{"month",9},{"day",10},{"hours_utc",4.}});
 if(!std::getenv("VSGRAYSIM_NAVAL_SKIP_ENTRY")){
 json drop={{"id","entry-target"},{"position_m",{35,3,25}},{"velocity_mps",{.5,-3,0}},{"source",{{"type","box"},{"dimensions",{12,6,12}},{"cell_size_m",.1}}},{"material",{{"density_kg_m3",1400},{"color_rgba",{.7,.28,.08,1}}}},{"physics",{{"motion","dynamic"},{"fracture",true},{"support","none"}}}};scene.edit(json::array({{{"kind","add"},{"object",drop}}}),scene.snapshot()->revision);scene.schedule({{"kind","fracture"},{"object","entry-target"},{"tick",scene.snapshot()->tick+1},{"space","object"},{"point_m",{.6,.3,.6}},{"normal",{1,0,0}},{"radius_m",5},{"energy_j",1e7}});const double entryBase=scene.snapshot()->timeSeconds();camera({43,4,35},{35,0,25});r["entry_frames"]=json::array();size_t maxSpray=0;
 for(int i=1;i<=45;++i){QElapsedTimer t;t.start();scene.setPaused(false);auto step=scene.advanceTo(entryBase+i*.04,8);scene.setPaused(true);require(!step.pendingSteps,"naval companion water entry dropped physics ticks");const double update=t.nsecsElapsed()/1e6,draw=render();const auto s=scene.snapshot();maxSpray=std::max(maxSpray,s->ocean->splashes.size());for(const auto& [id,o]:s->objects)require(feature.display().placements.at(id)->matrix==o.pose(s->tick,s->fixedStep),"entry fragment display differs from physical pose");r["entry_frames"].push_back({{"seconds",s->timeSeconds()},{"advance_simulation_ms",40},{"buoyancy_wall_ms",step.buoyancyMs},{"water_total_wall_ms",step.waterMs},{"advance_wall_ms",update},{"render_wall_ms",draw},{"complete_wall_ms",update+draw},{"splash_events",s->ocean->splashes.size()}});if(i%2)capture(QString("naval-entry-%1").arg(i,3,10,QChar('0')).toStdString());}
 require(maxSpray>0,"naval companion fragments failed to produce water-entry spray");r["maximum_entry_splash_events"]=maxSpray;r["spray_scope"]="visual ballistic droplets; not additional liquid mass, colliders or a 3D fluid solver";
 }else r["entry_scope"]="explicitly skipped for visual-only legacy comparison";
 for(const char* key:{"advance_wall_ms","render_submit_wait_ms","buoyancy_wall_ms","water_drag_wall_ms","water_total_wall_ms","complete_wall_ms"}){std::vector<double> values;for(const auto& f:r["frames"])values.push_back(f.at(key));std::sort(values.begin(),values.end());r[std::string(key)+"_median"]=values[values.size()/2];r[std::string(key)+"_p95"]=values[size_t(.95*(values.size()-1))];}
 std::ofstream(directory/"naval-acceptance.json")<<r.dump(2)<<'\n';std::cout<<"PASS: full-size textured cruiser, voxel buoyancy, native display/collision ranges and weather cases\n";
}
